import{_ as s,o as i,c as t,aj as e}from"./chunks/framework.Cn87zHeG.js";const n="/onerobot-H1/images/intelligent/h1-dual-board-network.svg",b=JSON.parse('{"title":"智能版：连接与使用","description":"","frontmatter":{"title":"智能版：连接与使用","outline":[2,3]},"headers":[],"relativePath":"getting-started/intelligent.md","filePath":"getting-started/intelligent.md"}'),d={name:"getting-started/intelligent.md"};function r(h,a,l,p,o,c){return i(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="智能版-连接与使用" tabindex="-1">智能版：连接与使用 <a class="header-anchor" href="#智能版-连接与使用" aria-label="Permalink to &quot;智能版：连接与使用&quot;">​</a></h1><p>H1 智能版在 RK3576 主控之外增加 NVIDIA 计算板。开发电脑先连接 H1，再通过 RK3576 登录 NVIDIA 计算板；应用可以部署在 NVIDIA 计算板上，通过机器人接口完成二次开发。</p><p>本页说明智能版的双板连接、登录和 NVIDIA 计算板使用方法。开发电脑统一使用<strong>原生 Zenoh（<code>rmw_zenoh_cpp</code>）</strong>，固件检查与环境准备见 <a href="./communication.html">ROS 2 通信配置</a>。</p><h2 id="connection" tabindex="-1">双板连接与地址 <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;双板连接与地址 {#connection}&quot;">​</a></h2><p><img src="'+n+`" alt="H1 智能版双板连接：电脑或路由器连接 RK3576 对外网口，RK3576 通过 USB 转网口模块连接 NVIDIA 计算板；NVIDIA 计算板地址由内部 DHCP 分配。"></p><table tabindex="0"><thead><tr><th>连接位置</th><th>用途</th><th>地址规则</th></tr></thead><tbody><tr><td>① RK3576 对外网口</td><td>连接开发电脑或路由器</td><td>网线直连默认 <code>10.42.0.2</code>；接入提供 DHCP 的路由器或电脑时，也可获得分配的 IP</td></tr><tr><td>② RK3576 内部网口（以下以 <code>orin0</code> 为例）</td><td>经 USB 3.0 转网口模块、网线连接 NVIDIA 计算板；提供 DHCP</td><td>交付说明中的默认地址为 <code>192.168.251.1</code>，可用下文命令核对设备实际配置</td></tr><tr><td>NVIDIA 计算板网口</td><td>连接 RK3576 内部网络</td><td>通过 DHCP 获取地址；<code>192.168.251.37</code> 仅为示例，登录前先查询</td></tr></tbody></table><p>电脑网线直连时，将电脑对应网口的 IPv4 地址设为同网段，例如 <strong><code>10.42.0.1/24</code></strong>，子网掩码为 <code>255.255.255.0</code>。不要与机器人的 <code>10.42.0.2</code> 重复。</p><p>电脑和 H1 接入同一路由器时，使用路由器分配给 H1 的实际地址。后续 SSH、SCP 和电脑 Zenoh 配置中的 H1 地址都应一起替换。机器人热点及 WiFi 局域网的连接方式见<a href="./../diagnostics/services.html#ssh-login">SSH 远程登录机器人</a>。</p><h3 id="internet-access" tabindex="-1">计算板联网方式 <a class="header-anchor" href="#internet-access" aria-label="Permalink to &quot;计算板联网方式 {#internet-access}&quot;">​</a></h3><p>NVIDIA 计算板安装在机器人内部，通过内部有线网络连接 RK3576 主控板。需要联网时，将机器人对外网口接入可访问互联网的有线网络，计算板通过主控共享网络，<strong>无需单独配置 Wi-Fi</strong>。</p><p>电脑网线直连机器人用于本地调试，不代表机器人已接入互联网。在计算板上下载依赖、获取源码前，先确保主控板已接入可上网的网络。后续登录仍按“开发电脑 → RK3576 主控板 → NVIDIA 计算板”的顺序进行。</p><h3 id="系统环境" tabindex="-1">系统环境 <a class="header-anchor" href="#系统环境" aria-label="Permalink to &quot;系统环境&quot;">​</a></h3><table tabindex="0"><thead><tr><th>设备</th><th>系统</th><th>ROS 2</th><th>通信实现</th></tr></thead><tbody><tr><td>RK3576 主控</td><td>Ubuntu 24.04</td><td>Jazzy</td><td><code>rmw_zenoh_cpp</code></td></tr><tr><td>NVIDIA 计算板</td><td>Ubuntu 24.04</td><td>Jazzy</td><td><code>rmw_zenoh_cpp</code></td></tr><tr><td>开发电脑</td><td>Ubuntu 24.04</td><td>Jazzy</td><td>按<a href="./communication.html#pc-zenoh">共用通信配置</a>加载 <code>rmw_zenoh_cpp</code></td></tr></tbody></table><p>板端环境按设备固件和交付配置使用。开发电脑的软件包与 router 配置见 <a href="./communication.html#pc-zenoh">Zenoh 环境</a>。</p><h2 id="login" tabindex="-1">登录 RK3576 和 NVIDIA 计算板 <a class="header-anchor" href="#login" aria-label="Permalink to &quot;登录 RK3576 和 NVIDIA 计算板 {#login}&quot;">​</a></h2><h3 id="_1-在开发电脑上登录-rk3576" tabindex="-1">1. 在开发电脑上登录 RK3576 <a class="header-anchor" href="#_1-在开发电脑上登录-rk3576" aria-label="Permalink to &quot;1. 在开发电脑上登录 RK3576&quot;">​</a></h3><p><strong>执行位置：开发电脑终端。</strong> 以下以网线直连为例：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.42.0.2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wlab@10.42.0.2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>RK3576 用户名为 <strong><code>wlab</code></strong>，默认密码为 <strong><code>wlab</code></strong>；若已修改密码，使用修改后的密码。输入密码时终端不显示字符。首次连接时核对目标机器的 SSH 主机指纹，再确认连接。</p><p>登录成功后，这个终端已经在 <strong>RK3576</strong> 上执行命令。</p><h3 id="_2-在-rk3576-上查询-nvidia-计算板的实际-ip" tabindex="-1">2. 在 RK3576 上查询 NVIDIA 计算板的实际 IP <a class="header-anchor" href="#_2-在-rk3576-上查询-nvidia-计算板的实际-ip" aria-label="Permalink to &quot;2. 在 RK3576 上查询 NVIDIA 计算板的实际 IP&quot;">​</a></h3><p><strong>执行位置：已登录 RK3576 的终端。</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 先查看网口名称及地址</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -br</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> addr</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 以下以内部网口 orin0 为例，按实际名称替换</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -br</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orin0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看该网口上的邻居地址，找到 NVIDIA 计算板</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> neigh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orin0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>网口名称区分大小写：若设备显示的是 <code>Orin0</code> 或其他名称，请按实际名称替换命令中的 <code>orin0</code>。也可使用 <code>arp -a</code> 查看邻居信息，注意区分内部网口与其他网口。邻居表是缓存，没有条目时先检查 NVIDIA 计算板是否上电、内部网线与 USB 转网口模块是否连接，以及 DHCP 是否分配了地址；不能仅凭空表判断 NVIDIA 计算板故障。</p><h3 id="_3-从-rk3576-登录-nvidia-计算板" tabindex="-1">3. 从 RK3576 登录 NVIDIA 计算板 <a class="header-anchor" href="#_3-从-rk3576-登录-nvidia-计算板" aria-label="Permalink to &quot;3. 从 RK3576 登录 NVIDIA 计算板&quot;">​</a></h3><p><strong>执行位置：仍在 RK3576 终端。</strong> 将下面的示例地址替换为上一步查到的 NVIDIA 计算板 IP：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nvidia@192.168.251.37</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>NVIDIA 计算板用户名为 <strong><code>nvidia</code></strong>。交付环境配置了 RK3576 到 NVIDIA 计算板的免密登录；如果提示输入密码或认证失败，请核对设备交付的账号与 SSH 配置。这一免密配置适用于 <strong>RK3576 → NVIDIA 计算板</strong>，不等于电脑可以直接免密登录 NVIDIA 计算板。</p><p>进入 NVIDIA 计算板后，可用下面的只读命令确认当前用户、主机和架构：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">whoami</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hostname</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>嵌套登录时，在 NVIDIA 计算板输入一次 <code>exit</code> 返回 RK3576，再输入一次 <code>exit</code> 返回开发电脑。</p><h2 id="files-and-tools" tabindex="-1">传输文件与访问工具 <a class="header-anchor" href="#files-and-tools" aria-label="Permalink to &quot;传输文件与访问工具 {#files-and-tools}&quot;">​</a></h2><h3 id="将文件上传到-rk3576" tabindex="-1">将文件上传到 RK3576 <a class="header-anchor" href="#将文件上传到-rk3576" aria-label="Permalink to &quot;将文件上传到 RK3576&quot;">​</a></h3><p><strong>执行位置：开发电脑新开的终端。</strong> 用实际文件替换 <code>example.zip</code>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./example.zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wlab@10.42.0.2:~/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>文件保存到 RK3576 的 <code>/home/wlab/</code>。传输整个目录时可以使用 <code>scp -r ./project wlab@10.42.0.2:~/</code>。</p><h3 id="将文件继续传到-nvidia-计算板" tabindex="-1">将文件继续传到 NVIDIA 计算板 <a class="header-anchor" href="#将文件继续传到-nvidia-计算板" aria-label="Permalink to &quot;将文件继续传到 NVIDIA 计算板&quot;">​</a></h3><p><strong>执行位置：RK3576 终端。</strong> 使用实际 NVIDIA 计算板 IP：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/example.zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nvidia@192.168.251.37:~/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>文件保存到 NVIDIA 计算板的 <code>/home/nvidia/</code>。进入 NVIDIA 计算板后，可在该目录下准备应用工作空间，按对应示例的依赖、编译和启动说明继续操作。</p><h3 id="打开机器人网页工具" tabindex="-1">打开机器人网页工具 <a class="header-anchor" href="#打开机器人网页工具" aria-label="Permalink to &quot;打开机器人网页工具&quot;">​</a></h3><p>在<strong>开发电脑浏览器</strong>中使用 H1 的对外地址访问。网线直连示例：</p><table tabindex="0"><thead><tr><th>工具</th><th>地址</th><th>使用说明</th></tr></thead><tbody><tr><td>网络配置工具</td><td><code>http://10.42.0.2:8080/</code></td><td><a href="./../faq/network-ota.html">网络配置与 OTA</a></td></tr><tr><td>出厂与跑机测试工具</td><td><code>http://10.42.0.2:8090/</code></td><td><a href="./../faq/factory-test.html">出厂与跑机测试</a></td></tr></tbody></table><p>接入路由器时，将地址中的 <code>10.42.0.2</code> 替换为 H1 的实际 IP。这里使用的是 RK3576 对外地址，NVIDIA 计算板地址用于登录和访问 NVIDIA 计算板上运行的应用。</p><h2 id="pc-zenoh" tabindex="-1">开发电脑的 Zenoh 环境 <a class="header-anchor" href="#pc-zenoh" aria-label="Permalink to &quot;开发电脑的 Zenoh 环境 {#pc-zenoh}&quot;">​</a></h2><p>标准版与智能版共用<a href="./communication.html#pc-zenoh">开发电脑的 Zenoh 配置</a>，包括软件包安装、电脑 router 和终端环境设置。完成后再进行下方的板端通信验证。</p><h2 id="verify" tabindex="-1">验证通信与排查 <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;验证通信与排查 {#verify}&quot;">​</a></h2><p>开发电脑的验证步骤见 <a href="./communication.html#verify">ROS 2 通信配置：验证通信与排查</a>。</p><h3 id="在-nvidia-计算板上验证" tabindex="-1">在 NVIDIA 计算板上验证 <a class="header-anchor" href="#在-nvidia-计算板上验证" aria-label="Permalink to &quot;在 NVIDIA 计算板上验证&quot;">​</a></h3><p><strong>执行位置：已登录 NVIDIA 计算板的终端。</strong> 使用板端交付环境：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/ros/jazzy/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$RMW_IMPLEMENTATION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /scan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --once</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>RMW_IMPLEMENTATION</code> 应为 <code>rmw_zenoh_cpp</code>。若为空或显示其他实现，先核对该设备的交付环境与 Shell 加载配置。收到雷达消息后，再按目标应用说明准备依赖和启动应用。</p><h3 id="常见检查点" tabindex="-1">常见检查点 <a class="header-anchor" href="#常见检查点" aria-label="Permalink to &quot;常见检查点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>先检查什么</th></tr></thead><tbody><tr><td>电脑无法连接 <code>10.42.0.2</code></td><td>网线是否插在 H1 对外网口；电脑是否为 <code>10.42.0.x/24</code>；路由器连接时是否换成了实际 IP</td></tr><tr><td>RK3576 能登录，但找不到 NVIDIA 计算板</td><td>NVIDIA 计算板上电、内部网线和 USB 转网口模块、内部网口地址及 DHCP 分配；网口名按实际设备核对，邻居缓存可能暂时没有条目</td></tr><tr><td>NVIDIA 计算板登录提示认证失败</td><td>确认命令是在 RK3576 上执行，核对 NVIDIA 计算板实际 IP 与设备交付的 SSH 配置</td></tr><tr><td>NVIDIA 计算板无法联网</td><td>请联系技术支持协助排查</td></tr><tr><td>SSH 正常，但电脑没有机器人话题</td><td>按<a href="./communication.html#verify">共用通信排查</a>核对电脑环境、router 及实际消息</td></tr><tr><td>有话题但 <code>/scan</code> 没有数据</td><td>核对机器人雷达服务、话题发布状态及通信链路；不能仅凭话题列表判定已连通</td></tr></tbody></table><p>以上检查只读取状态和雷达消息。运动控制及应用运行按对应示例的前置条件操作；机器人服务说明见<a href="./../diagnostics/services.html">机内服务与重启</a>。</p>`,55)])])}const g=s(d,[["render",r]]);export{b as __pageData,g as default};
